#include <bits/stdc++.h>
using namespace std;
const long long MOD=998244353;
bool check(int n,int x,int c ,int side,const vector<int>& pos){
    int d= x-1-c;
    int px= (side? c+1: n-d);
    for(int i:pos){
        int pre= min(c,i)+max(0,i-(n-d));
        int suff= max(0,c-i+1)+min(d,n-i+1);
        
        if(i<px){
            if(suff!= (n-i)/2) return false;
            
        }
        else if(i>px){
            if(pre!=(i-1)/2) return false;
            
        }
        else{
            if(pre!=(i-1)/2 && suff!=(n-i)/2) return false;
        }
    }
    return true;
}
void solve(){
    int n;
    cin>>n;
    vector<int> a(n+1);
    vector<vector<int>> where(n+1);
    for(int i=1;i<=n;i++){
        cin>>a[i];
        where[a[i]].push_back(i);
    }
    if(n==1) {
        cout<<(a[1]==1)<<endl;
        return;
    }
    vector<long long> dp(n+1), ndp(n+1);
    dp[0]=1;
    for(int x=1;x<n;x++){
        fill(ndp.begin(),ndp.end(),0);
        
        for(int c=0;c<x;c++){
            if(dp[c]==0) continue;
            
            if(check(n,x,c,0,where[x])){
                ndp[c]+=dp[c];
                if(ndp[c]>=MOD) ndp[c]-=MOD;
            }
            
            if(check(n,x,c,1,where[x])){
                ndp[c+1]+=dp[c];
                if(ndp[c+1]>=MOD) ndp[c+1]-=MOD;
            }
        }
    dp.swap(ndp);
}
long long ans=0;

for(int c=0;c<n;c++){
    if(dp[c] && check(n,n,c,1,where[n])){
        ans+=dp[c];
        if(ans>=MOD) ans-=MOD;
    }
}

cout<<ans<<endl;
}
int main() {
	// your code goes here
int t;
cin>>t;
while(t--){
    solve();
}
return 0;
}
